def trapWater(arr):
    if not arr:
        return 0

    left, right = 0, len(arr) - 1
    max_left = max_right = 0
    water_trapped = 0

    while left < right:
        if arr[left] < arr[right]:
            if arr[left] >= max_left:
                max_left = arr[left]
            else:
                water_trapped += max_left - arr[left]
            left += 1
        else:
            if arr[right] >= max_right:
                max_right = arr[right]
            else:
                water_trapped += max_right - arr[right]
            right -= 1

    return water_trapped

def largestSquare(matrix):
    if not matrix or not matrix[0]:
        return 0

    k = len(matrix)
    dp = [[0] * k for _ in range(k)]
    max_side = 0

    for i in range(k):
        for j in range(k):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

