from typing import List

def rank_scores(scores: List[int], target: int) -> int:
    # Validate input types
    if not isinstance(scores, list) or not all(isinstance(score, int) for score in scores):
        raise TypeError("'scores' should be a list of integers")
    if not isinstance(target, int):
        raise TypeError("'target' should be an integer")

    # Handle empty scores list
    if not scores:
        return -1

    # Sort scores in descending order
    sorted_scores = sorted(scores, reverse=True)

    # Create a dictionary to store the rank of each unique score
    rank_dict = {}
    rank = 1
    for i, score in enumerate(sorted_scores):
        if score not in rank_dict:
            rank_dict[score] = rank
        rank += 1

    # Return the rank of the target score
    return rank_dict.get(target, -1)

