def max_binary(s: str, k: int) -> str:
    # Count the number of '0's in the string
    zero_count = s.count('0')

    # If k is greater than or equal to the number of '0's, flip all '0's
    if k >= zero_count:
        return s.replace('0', '1')

    # Otherwise, flip the first k '0's
    result = []
    flip_count = 0
    for char in s:
        if char == '0' and flip_count < k:
            result.append('1')
            flip_count += 1
        else:
            result.append(char)

    return ''.join(result)

