def coin_change(coins, amount):
    # Initialize the DP table with a value greater than the maximum possible number of coins
    dp = [amount + 1] * (amount + 1)
    # Base case: 0 coins are needed to make up amount 0
    dp[0] = 0

    # Iterate through all amounts from 1 to the target amount
    for a in range(1, amount + 1):
        # Iterate through all coin denominations
        for c in coins:
            if a - c >= 0:
                # Update the DP table with the minimum number of coins needed
                dp[a] = min(dp[a], 1 + dp[a - c])

    # If dp[amount] is still amount + 1, it means no solution was found
    if dp[amount] == amount + 1:
        return -1
    return dp[amount]

